(function(root){'use strict';
const C=root.NutriFoodCaptureContract,K=root.NutriFoodCaptureController;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

// Optional synthetic meal detail; no food database, automatic nutrition math or new storage domain.
const INGREDIENT_FORMAT='manual-ingredients-v1',INGREDIENT_MAX=20;let ingredientMountSerial=0;
function ingredientFail(message){throw Error(message);}
function ingredientNoHooks(value){for(let p=value;p;p=Object.getPrototypeOf(p))if(Object.getOwnPropertyDescriptor(p,'toJSON'))ingredientFail('食材明细格式无法安全读取；原记录保留，请取消后核对。');}
function ingredientObject(value,keys){if(!value||Object.getPrototypeOf(value)!==Object.prototype)ingredientFail('食材明细格式不受支持；未覆盖原记录。');ingredientNoHooks(value);const actual=Reflect.ownKeys(value);if(actual.length!==keys.length||actual.some(k=>typeof k!=='string'||!keys.includes(k)))ingredientFail('食材明细字段不受支持；未覆盖原记录。');for(const key of keys){const d=Object.getOwnPropertyDescriptor(value,key);if(!d||!Object.prototype.hasOwnProperty.call(d,'value')||!d.enumerable)ingredientFail('食材明细格式不受支持；未覆盖原记录。');}return value;}
function ingredientName(value,editableC1=false){if(typeof value!=='string'||/[\u0000-\u001f\u007f]/.test(value)||(!editableC1&&/[\u0080-\u009f]/.test(value)))ingredientFail('请填写食材名称，不要包含控制字符。');const name=value.trim().normalize('NFC').replace(/\s+/g,' ');if(!name||Array.from(name).length>60)ingredientFail('每条食材名称需为 1–60 个字符，不能只填空格。');return editableC1&&/[\u0080-\u009f]/.test(value)?value:name;}
function ingredientGrams(value,stored=false){if(value===null||(!stored&&typeof value==='string'&&!value.trim()))return null;if(stored){if(typeof value!=='number')ingredientFail('已存食材克数格式不受支持；未覆盖原记录。');}else if(typeof value!=='string'||!/^\d+(?:\.\d{1,2})?$/.test(value.trim()))ingredientFail('食材克数请填正数，最多 2 位小数；未知请留空。');const n=Number(value);if(!Number.isFinite(n)||n<=0||n>10000||n!==Math.round(n*100)/100)ingredientFail('食材克数须大于 0 且不超过 10000 g，最多 2 位小数；未知请留空。');return n;}
function ingredientDetail(value,editableC1=false){ingredientObject(value,['format','items']);if(value.format!==INGREDIENT_FORMAT)ingredientFail('食材明细版本不受支持；未覆盖原记录。');const items=value.items;if(!Array.isArray(items)||Object.getPrototypeOf(items)!==Array.prototype||items.length>INGREDIENT_MAX)ingredientFail('食材明细最多支持 20 项；原记录未覆盖。');ingredientNoHooks(items);if(Reflect.ownKeys(items).length!==items.length+1)ingredientFail('食材明细列表格式不受支持。');const seen=new Set(),checked=[];for(let i=0;i<items.length;i++){const d=Object.getOwnPropertyDescriptor(items,String(i));if(!d||!Object.prototype.hasOwnProperty.call(d,'value')||!d.enumerable)ingredientFail('食材明细列表格式不受支持。');const row=ingredientObject(d.value,['name','grams']),name=ingredientName(row.name,editableC1);if(name!==row.name)ingredientFail('已存食材名称格式不受支持；未覆盖原记录。');const duplicate=name.toLowerCase();if(seen.has(duplicate))ingredientFail('存在同名食材，请手动合并后再保存；不会自动累加。');seen.add(duplicate);checked.push({name,grams:ingredientGrams(row.grams,true)});}return {format:INGREDIENT_FORMAT,items:checked};}
function mount(host,{date,id,initial=null,save,isLocked=()=>false,onDirty=()=>{},start='camera'}={}){let active=true,origin='manual',url=null,selection=0,busy=false,pendingImage=null,cameraPending=false,ingredientUsed=false,ingredientIssue=null,ingredientCorrection=false,ingredientSerial=0;const ingredientPrefix='fc-ingredient-'+(++ingredientMountSerial)+'-';let initialIngredients=[];try{const descriptor=initial&&Object.getOwnPropertyDescriptor(initial,'manualIngredients');if(descriptor){if(!Object.prototype.hasOwnProperty.call(descriptor,'value')||!descriptor.enumerable)ingredientFail('食材明细格式不受支持；未覆盖原记录。');initialIngredients=ingredientDetail(descriptor.value,true).items;ingredientCorrection=initialIngredients.some(row=>/[\u0080-\u009f]/.test(row.name));ingredientUsed=true;}}catch(error){ingredientIssue=error.message;}const message=t=>{if(active)host.querySelector('.fc-status').textContent=t;};
host.innerHTML=`<section class="fc-panel"><h2 class="glass-review-title">核对这一餐</h2><p>本机预览，不上传照片。当前仅可保存合成演示记录；照片不存入账号，刷新后清除。</p><nav><button type="button" data-fc="camera">相机</button><button type="button" data-fc="manual">手动输入</button><button type="button" data-fc="gallery">选择图片</button></nav><video class="fc-preview" autoplay muted playsinline hidden></video><img class="fc-preview" alt="仅本机预览的食物照片" hidden><button type="button" data-fc="shutter" hidden>拍照</button><button type="button" data-fc="remove" hidden>移除本机预览 · 保留填写</button><input data-fc-file type="file" accept="image/*" hidden><p class="fc-status" role="status">照片识别与语音服务未连接，可手工填写合成示例。</p><p class="fc-draft-note">未提交的填写只在当前编辑器中，不是已保存草稿；离开前请核对。只有下方确认保存才写入本机合成记录。</p><form data-fc-form><label>食物名称<input name="name" maxlength="100" required></label><div class="fc-grid"><label>摄入日期<input type="date" name="date" value="${esc(date)}" required></label><label>时间<input type="time" name="time" value="12:00" required></label><label>餐次<select name="slot"><option value="breakfast">早餐</option><option value="lunch">午餐</option><option value="dinner">晚餐</option><option value="snack">加餐</option></select></label><label>份量 g（未知留空）<input name="grams" type="number" min="0" step="any"></label></div><section class="fc-ingredients" data-fc-ingredients aria-label="手工食材明细"><header class="fc-ingredients-heading"><h3>手工食材明细 <small>可选</small></h3><button type="button" data-fc="ingredient-add">＋ 添加食材</button></header><p class="fc-ingredients-note">不自动重算营养，也不根据照片识别食材。每项克数未知请留空；同名食材请手动合并。</p><p class="fc-ingredients-error" data-fc-ingredient-error role="alert" hidden></p><ul class="fc-ingredient-list" data-fc-ingredient-list></ul><p class="fc-ingredients-empty" data-fc-ingredient-empty>尚未填写食材明细；可以只保留整餐记录。</p><p class="fc-ingredients-limit">最多 20 项，每项名称最多 60 字；克数为正数、最多两位小数，上限 10000 g（输入限制，不是摄入建议）。未确认保存前的增删仅影响当前填写。</p></section><section class="fc-nutrition-main" aria-label="编辑本次摄入营养"><h3>编辑营养</h3><p>本次摄入总量 · 手工填写，未知留空；修改克数不会自动换算营养。</p><div class="fc-grid">${Object.entries(C.fields).filter(([k])=>['kcal','protein','carb','fat'].includes(k)).map(([k,[label,unit]])=>`<label>${label} ${unit}<input name="${k}" type="number" min="0" step="any" placeholder="未知留空"></label>`).join('')}</div></section><details><summary>更多营养成分 · 24 项（可选）</summary><div class="fc-grid">${Object.entries(C.fields).filter(([k])=>!['kcal','protein','carb','fat'].includes(k)).map(([k,[label,unit]])=>`<label>${label} ${unit}<input name="${k}" type="number" min="0" step="any" placeholder="未知留空"></label>`).join('')}</div></details><p>钠 mg 与盐 g 分别记录，不互相冒充；空白不是 0。图片不能确定份量、油盐和完整营养。</p><label><input type="checkbox" name="confirmedSynthetic" required>仅保存合成示例；已核对名称、日期、餐次和所填营养值，同意存此浏览器。</label><button type="submit">确认保存合成记录</button></form></section>`;
if(initial){const form=host.querySelector('[data-fc-form]');for(const key of ['name','date','time','slot','grams',...Object.keys(C.fields)]){if(form.elements[key]){const value=initial.nutrients&&Object.prototype.hasOwnProperty.call(initial.nutrients,key)?initial.nutrients[key]?.value:initial[key];form.elements[key].value=value==null?'':String(value);}}}

const ingredientList=host.querySelector('[data-fc-ingredient-list]'),ingredientAdd=host.querySelector('[data-fc="ingredient-add"]'),ingredientEmpty=host.querySelector('[data-fc-ingredient-empty]'),ingredientError=host.querySelector('[data-fc-ingredient-error]');
function ingredientNodes(){return Array.from(ingredientList.querySelectorAll('[data-fc-ingredient]'));}
function syncIngredients(){if(!active)return;const locked=busy||!!ingredientIssue||isLocked();if(!active)return;ingredientAdd.disabled=locked||ingredientNodes().length>=INGREDIENT_MAX;ingredientList.querySelectorAll('input,button').forEach(n=>{n.disabled=locked;});ingredientEmpty.hidden=ingredientNodes().length>0;if(ingredientIssue){ingredientError.hidden=false;ingredientError.textContent=ingredientIssue+' 食材格式未核对，已阻止保存；可关闭记录，原已存行不变。';host.querySelector('button[type=submit]').disabled=true;}else if(ingredientCorrection){ingredientError.hidden=false;ingredientError.textContent='已存食材名称含控制字符，原字符串与原记录均未改动。请逐条手动重填有效名称，或明确移除该食材后再确认保存；系统不会自动清理。';}}
function appendIngredient(row={name:'',grams:null}){const li=document.createElement('li'),serial=++ingredientSerial,nameId=ingredientPrefix+serial+'-name',gramsId=ingredientPrefix+serial+'-grams';li.className='fc-ingredient-row';li.dataset.fcIngredient=String(serial);li.innerHTML=`<label for="${nameId}">食材名称<input id="${nameId}" data-fc-ingredient-name type="text" maxlength="120" required placeholder="手工填写"></label><label for="${gramsId}">克数 g<input id="${gramsId}" data-fc-ingredient-grams type="number" min="0.01" max="10000" step="0.01" placeholder="未知留空"></label><button type="button" data-fc="ingredient-remove" aria-label="移除第 ${serial} 条食材，仅影响未保存填写">×</button>`;li.querySelector('[data-fc-ingredient-name]').value=row.name;li.querySelector('[data-fc-ingredient-grams]').value=row.grams===null?'':String(row.grams);ingredientList.append(li);return li;}
function changeIngredient(action,button){if(!active||busy||ingredientIssue||isLocked()||!active)return;if(action==='ingredient-add'){if(ingredientNodes().length>=INGREDIENT_MAX){message('最多填写 20 项食材；可以先编辑或移除已有项。');return;}const li=appendIngredient();ingredientUsed=true;onDirty();if(!active)return;syncIngredients();if(active)li.querySelector('[data-fc-ingredient-name]').focus();}else{const li=button.closest('[data-fc-ingredient]');if(!li||!ingredientList.contains(li))return;const all=ingredientNodes(),at=all.indexOf(li);li.remove();ingredientUsed=true;onDirty();if(!active)return;syncIngredients();const next=ingredientNodes()[Math.min(at,ingredientNodes().length-1)];if(active)(next?.querySelector('[data-fc-ingredient-name]')||ingredientAdd).focus();message('食材已从当前填写移除；确认保存前，原餐食记录不变。');}}
function readIngredients(){if(ingredientIssue)ingredientFail(ingredientIssue);return ingredientDetail({format:INGREDIENT_FORMAT,items:ingredientNodes().map(li=>({name:ingredientName(li.querySelector('[data-fc-ingredient-name]').value),grams:ingredientGrams(li.querySelector('[data-fc-ingredient-grams]').value)}))});}
initialIngredients.forEach(appendIngredient);syncIngredients();
const video=host.querySelector('video'),img=host.querySelector('img'),shutter=host.querySelector('[data-fc="shutter"]'),file=host.querySelector('[data-fc-file]'),remove=host.querySelector('[data-fc="remove"]');
const controller=K.create({mediaDevices:root.navigator?.mediaDevices,onState:(state,e)=>{if(state==='camera-error')message(e?.name==='NotAllowedError'?'相机权限未允许，可手动输入或选择图片。':e?.message||'相机不可用，可手动输入或选择图片。');}});
function syncRemove(){remove.hidden=!active||!(url||pendingImage||cameraPending||!video.hidden);remove.disabled=busy||isLocked();}
function stop(){selection++;controller.leave();video.srcObject=null;video.hidden=true;shutter.hidden=true;cameraPending=false;if(pendingImage){pendingImage.release();pendingImage=null;}syncRemove();}
function revoke(){if(url){URL.revokeObjectURL(url);url=null;}}
async function camera(){stop();const ticket=selection;img.hidden=true;cameraPending=true;syncRemove();message('正在请求相机权限；可随时切换手动输入或移除预览。');const s=await controller.camera();if(!active||ticket!==selection)return;if(isLocked()){stop();return;}cameraPending=false;if(!s){syncRemove();return;}video.srcObject=s;video.hidden=false;shutter.hidden=false;origin='camera';syncRemove();message('只在本机预览。拍照后手工核对；AI识别服务未连接。');video.play().catch(()=>{if(active&&ticket===selection)message('请允许视频播放，或改用选择图片/手动记录。');});}
async function acceptFile(blob,source){
 if(!active||busy||isLocked())return;stop();const ticket=selection;
 if(!blob||!blob.type.startsWith('image/')){message('请选择有效图片，原填写已保留。');return;}
 if(blob.size>12*1024*1024){message('图片超过本地 12 MB 限制，请选择较小图片。未上传。');return;}
 message('正在本地读取图片…');let resource=null;
 try{
  const next=URL.createObjectURL(blob);let released=false;resource={release(){if(!released){released=true;URL.revokeObjectURL(next);}}};pendingImage=resource;syncRemove();
  const probe=new Image();await new Promise((resolve,reject)=>{probe.onload=resolve;probe.onerror=reject;probe.src=next;});
  if(!active||ticket!==selection||isLocked()){resource.release();return;}
  if(probe.naturalWidth*probe.naturalHeight>24000000)throw Error('图片像素过大');
  pendingImage=null;revoke();url=next;img.src=url;img.hidden=false;origin=source;onDirty();message('照片已在本机准备好；AI识别未连接。请手工核对，未知营养留空。照片不会保存到演示账号。');
 }catch(e){resource?.release();if(active&&ticket===selection)message('图片无法读取或像素过大，原填写已保留。未上传。');}
 finally{if(pendingImage===resource)pendingImage=null;if(active)syncRemove();}
}
function removePreview(){stop();revoke();img.removeAttribute('src');img.hidden=true;origin='manual';file.value='';syncRemove();message('已移除本机预览；文字、日期和营养填写均保留。照片未上传或保存。');host.querySelector('[name=name]').focus();}
function click(e){const b=e.target.closest('[data-fc]');if(!b)return;e.preventDefault();e.stopPropagation();if(busy||!active||isLocked()||!active)return;if(b.dataset.fc==='ingredient-add'||b.dataset.fc==='ingredient-remove'){changeIngredient(b.dataset.fc,b);return;}if(b.dataset.fc==='remove'){removePreview();return;}if(b.dataset.fc==='camera')camera();if(b.dataset.fc==='manual'){stop();message('手动记录：语音转写未连接，不会录音。');host.querySelector('[name=name]').focus();}if(b.dataset.fc==='gallery'){stop();file.click();}if(b.dataset.fc==='shutter'){if(!video.videoWidth||!video.videoHeight){message('相机尚未准备好');return;}const canvas=document.createElement('canvas'),factor=Math.min(1,1600/video.videoWidth);canvas.width=Math.round(video.videoWidth*factor);canvas.height=Math.round(video.videoHeight*factor);canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);const captureTicket=selection;canvas.toBlob(blob=>{if(active&&captureTicket===selection)acceptFile(blob,'camera');},'image/jpeg',.85);}}
function change(e){if(e.target===file){const selected=file.files?.[0];file.value='';if(selected)acceptFile(selected,'gallery');return;}onDirty();}
async function submit(e){if(!e.target.matches('[data-fc-form]'))return;e.preventDefault();e.stopPropagation();if(busy||!active||isLocked())return;const f=e.target;if(!f.reportValidity())return;try{const ingredientData=readIngredients();const data=Object.fromEntries(new FormData(f));data.confirmedSynthetic=f.elements.confirmedSynthetic.checked;data.origin=origin;let row=C.record(data,id);if(initial){row={...initial,...row,revision:(initial.revision||0)+1,previousRevision:initial.revision||0};for(const key of Object.keys(C.fields)){const old=initial.nutrients?.[key];if(old&&old.value===row.nutrients[key].value)row.nutrients[key]=JSON.parse(JSON.stringify(old));}row.note='人工校对的合成示例修订；非图像识别';}if(ingredientUsed)row.manualIngredients=ingredientData;busy=true;syncIngredients();f.querySelector('button[type=submit]').disabled=true;stop();await save(row);}catch(err){message(err.message||'保存未确认，请核对原操作；填写保留。');}finally{busy=false;if(active){f.querySelector('button[type=submit]').disabled=isLocked()||!!ingredientIssue;syncRemove();syncIngredients();}}}
function hidden(){if(document.hidden)stop();}
host.addEventListener('click',click);host.addEventListener('change',change);host.addEventListener('input',onDirty);host.addEventListener('submit',submit);document.addEventListener('visibilitychange',hidden);
if(start==='camera')camera();else message('语音服务未连接；可直接文字补录，不会录音或转写。');
return{dispose(){active=false;stop();controller.dispose();revoke();host.removeEventListener('click',click);host.removeEventListener('change',change);host.removeEventListener('input',onDirty);host.removeEventListener('submit',submit);document.removeEventListener('visibilitychange',hidden);}};
}
root.NutriFoodCaptureView={mount};
})(window);
